-- Rename trip_lists table to lists
-- This migration safely renames the table and updates all related objects

BEGIN;

-- Rename the table
ALTER TABLE trip_lists RENAME TO lists;

-- Update indexes (they should automatically rename with the table)
-- But let's be explicit for clarity
DROP INDEX IF EXISTS idx_trip_lists_user_id;
CREATE INDEX idx_lists_user_id ON lists(user_id);

-- Update the trigger (drop old, create new)
DROP TRIGGER IF EXISTS update_trip_lists_updated_at ON lists;
CREATE TRIGGER update_lists_updated_at BEFORE UPDATE ON lists
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- RLS Policies are automatically updated with the table name change
-- But let's verify they exist with correct names
DROP POLICY IF EXISTS "Users can view own lists" ON lists;
DROP POLICY IF EXISTS "Users can insert own lists" ON lists;
DROP POLICY IF EXISTS "Users can update own lists" ON lists;
DROP POLICY IF EXISTS "Users can delete own lists" ON lists;

-- Recreate RLS policies with clean names
CREATE POLICY "Users can view own lists" ON lists
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own lists" ON lists
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own lists" ON lists
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own lists" ON lists
  FOR DELETE USING (auth.uid() = user_id);

COMMIT;

-- Add weight_display_unit column to gear_items table
ALTER TABLE gear_items 
ADD COLUMN weight_display_unit text DEFAULT 'g' 
CHECK (weight_display_unit IN ('g', 'oz', 'lb', 'kg'));

-- Comment for clarity
COMMENT ON COLUMN gear_items.weight_display_unit IS 'User-preferred display unit for weight (stored value always in grams)';

-- Add URL field to gear_items table
-- This stores the product URL or link from the original source (e.g., LighterPack, manufacturer)

ALTER TABLE gear_items 
ADD COLUMN url TEXT;

-- Add comment for clarity
COMMENT ON COLUMN gear_items.url IS 'Product URL or link from import source or manufacturer';

-- Create list_categories table
CREATE TABLE list_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    list_id UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    sort_index INTEGER NOT NULL DEFAULT 0,
    icon TEXT,
    color TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- Unique constraint to avoid duplicate names per list (or allow if you prefer)
    CONSTRAINT unique_list_category_name UNIQUE (list_id, name)
);

-- Enable RLS
ALTER TABLE list_categories ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for list_categories
-- Users can only access categories for lists they own
CREATE POLICY "Users can view their own list categories" ON list_categories
    FOR SELECT USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert categories for their own lists" ON list_categories
    FOR INSERT WITH CHECK (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can update their own list categories" ON list_categories
    FOR UPDATE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own list categories" ON list_categories
    FOR DELETE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

-- Create index for performance
CREATE INDEX idx_list_categories_list_id ON list_categories(list_id);
CREATE INDEX idx_list_categories_sort_index ON list_categories(list_id, sort_index);

-- Create updated_at trigger
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_list_categories_updated_at 
    BEFORE UPDATE ON list_categories 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

-- Create listed_gear_items table (junction table for gear items in lists with metadata)
CREATE TABLE listed_gear_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gear_id UUID NOT NULL REFERENCES gear_items(id) ON DELETE RESTRICT,
    list_category_id UUID REFERENCES list_categories(id) ON DELETE SET NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    worn BOOLEAN NOT NULL DEFAULT false,
    weight_g_override INTEGER, -- nullable, allows override of gear item weight
    notes TEXT, -- nullable
    sort_index INTEGER, -- nullable, for custom ordering within category
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE listed_gear_items ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for listed_gear_item
-- Users can only access listed gear items for gear they own
CREATE POLICY "Users can view their own listed gear items" ON listed_gear_items
    FOR SELECT USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert listed gear items for their own gear" ON listed_gear_items
    FOR INSERT WITH CHECK (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
        AND (
            list_category_id IS NULL OR
            list_category_id IN (
                SELECT lc.id FROM list_categories lc
                JOIN lists l ON l.id = lc.list_id
                WHERE l.user_id = auth.uid()
            )
        )
    );

CREATE POLICY "Users can update their own listed gear items" ON listed_gear_items
    FOR UPDATE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own listed gear items" ON listed_gear_items
    FOR DELETE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

-- Create indexes for performance
CREATE INDEX idx_listed_gear_item_gear_id ON listed_gear_items(gear_id);
CREATE INDEX idx_listed_gear_item_category_id ON listed_gear_items(list_category_id);
CREATE INDEX idx_listed_gear_item_category_sort ON listed_gear_items(list_category_id, sort_index);

-- Create updated_at trigger (created_at has DEFAULT NOW() so no trigger needed)
CREATE TRIGGER update_listed_gear_items_updated_at
    BEFORE UPDATE ON listed_gear_items
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- Drop and recreate gear_items table with new schema
-- WARNING: This will delete all existing gear data!

-- First, disable RLS and drop dependent objects
DROP POLICY IF EXISTS "Users can view their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can insert their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can update their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can delete their own gear items" ON gear_items;

-- Drop indexes
DROP INDEX IF EXISTS idx_gear_items_user_id;
DROP INDEX IF EXISTS idx_gear_items_category;

-- Drop triggers
DROP TRIGGER IF EXISTS update_gear_items_updated_at ON gear_items;

-- Drop the table (this will also drop the listed_gear_items foreign key constraint)
DROP TABLE IF EXISTS gear_items CASCADE;

-- Create weight unit display enum if it doesn't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'weight_unit_display') THEN
        CREATE TYPE weight_unit_display AS ENUM ('g', 'kg', 'lb', 'oz');
    END IF;
END $$;

-- Recreate gear_items table with new schema
CREATE TABLE gear_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    item_type TEXT NOT NULL,
    description TEXT NOT NULL,
    brand TEXT,
    model TEXT,
    consumable BOOLEAN NOT NULL DEFAULT false,
    price DECIMAL(10,2),
    weight_g INTEGER NOT NULL,
    weight_unit_display weight_unit_display NOT NULL,
    notes TEXT,
    image_url TEXT,
    url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE gear_items ENABLE ROW LEVEL SECURITY;

-- Create RLS policies
CREATE POLICY "Users can view their own gear items" ON gear_items
    FOR SELECT USING (user_id = auth.uid());

CREATE POLICY "Users can insert their own gear items" ON gear_items
    FOR INSERT WITH CHECK (user_id = auth.uid());

CREATE POLICY "Users can update their own gear items" ON gear_items
    FOR UPDATE USING (user_id = auth.uid());

CREATE POLICY "Users can delete their own gear items" ON gear_items
    FOR DELETE USING (user_id = auth.uid());

-- Create updated_at trigger (reuse existing function)
CREATE TRIGGER update_gear_items_updated_at
    BEFORE UPDATE ON gear_items
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- Note: This migration will break listed_gear_items foreign key constraints
-- You may need to recreate those relationships after running this migration

-- RPC function for transactional operations support
-- These functions help manage transactions in Supabase

-- Begin transaction function
CREATE OR REPLACE FUNCTION begin_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically handles transactions within functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Commit transaction function
CREATE OR REPLACE FUNCTION commit_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically commits at the end of functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Rollback transaction function
CREATE OR REPLACE FUNCTION rollback_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically rolls back on errors
    -- This is a placeholder for consistency with the ImportService
    RAISE EXCEPTION 'Transaction rollback requested';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Main import function for complete list structures
CREATE OR REPLACE FUNCTION import_complete_list(
    p_user_id UUID,
    p_list_data JSONB,
    p_categories_data JSONB,
    p_listed_gear_items_data JSONB
)
RETURNS JSONB AS $$
DECLARE
    v_list_id UUID;
    v_category JSONB;
    v_category_id UUID;
    v_category_map JSONB := '{}'::JSONB;
    v_gear_item JSONB;
    v_gear_id UUID;
    v_gear_map JSONB := '{}'::JSONB;
    v_listed_item JSONB;
    v_existing_gear RECORD;
    v_metadata JSONB;
    v_gear_items_created INT := 0;
    v_gear_items_reused INT := 0;
    v_categories_created INT := 0;
