    UPDATE lists 
    SET gear_ids = v_all_gear_ids
    WHERE id = v_list_id;

    -- Build return metadata
    v_metadata := jsonb_build_object(
        'gearItemsCreated', v_gear_items_created,
        'gearItemsReused', v_gear_items_reused,
        'categoriesCreated', v_categories_created,
        'listedGearItemsCreated', v_listed_items_created
    );

    -- Return the created list and metadata
    RETURN jsonb_build_object(
