GRANT EXECUTE ON FUNCTION commit_transaction() TO authenticated;
GRANT EXECUTE ON FUNCTION rollback_transaction() TO authenticated;
GRANT EXECUTE ON FUNCTION import_complete_list(UUID, JSONB, JSONB, JSONB) TO authenticated;

-- Fix the import_complete_list RPC function to properly cast weight_unit_display to enum type
-- This addresses the 400 Bad Request error when importing lists

CREATE OR REPLACE FUNCTION import_complete_list(
    p_user_id UUID,
    p_list_data JSONB,
    p_categories_data JSONB,
    p_listed_gear_items_data JSONB
)
RETURNS JSONB AS $$
DECLARE
    v_list_id UUID;
    v_category JSONB;
    v_category_id UUID;
    v_category_map JSONB := '{}'::JSONB;
    v_gear_item JSONB;
    v_gear_id UUID;
    v_gear_map JSONB := '{}'::JSONB;
    v_listed_item JSONB;
    v_existing_gear RECORD;
    v_metadata JSONB;
    v_gear_items_created INT := 0;
    v_gear_items_reused INT := 0;
    v_categories_created INT := 0;
    v_listed_items_created INT := 0;
    v_all_gear_ids UUID[] := '{}';
BEGIN
    -- Create the list
    INSERT INTO lists (name, user_id, gear_ids)
    VALUES (
        p_list_data->>'name',
        p_user_id,
        ARRAY[]::UUID[]
    )
    RETURNING id INTO v_list_id;

    -- Create categories and build mapping
    FOR v_category IN SELECT * FROM jsonb_array_elements(p_categories_data)
    LOOP
        INSERT INTO list_categories (
            list_id,
            name,
            sort_index,
            icon,
            color
        )
        VALUES (
            v_list_id,
            v_category->>'name',
            (v_category->>'sort_index')::INTEGER,
            v_category->>'icon',
            v_category->>'color'
        )
        RETURNING id INTO v_category_id;

        v_category_map := jsonb_set(v_category_map, ARRAY[v_category->>'name'], to_jsonb(v_category_id));
        v_categories_created := v_categories_created + 1;
    END LOOP;

    -- Process gear items and create listed gear items
    FOR v_listed_item IN SELECT * FROM jsonb_array_elements(p_listed_gear_items_data)
    LOOP
        v_gear_item := v_listed_item->'gearItem';

        -- Check if gear item already exists for this user
        SELECT id INTO v_existing_gear
        FROM gear_items
        WHERE user_id = p_user_id
            AND LOWER(TRIM(description)) = LOWER(TRIM(v_gear_item->>'description'))
            AND ABS(weight_g - (v_gear_item->>'weight_g')::INTEGER) <= 5
        LIMIT 1;

        IF FOUND THEN
            -- Reuse existing gear item
            v_gear_id := v_existing_gear.id;
            v_gear_items_reused := v_gear_items_reused + 1;
        ELSE
            -- Create new gear item
            INSERT INTO gear_items (
                user_id,
                description,
                item_type,
                brand,
                model,
                weight_g,
                weight_unit_display,
                consumable,
                price,
                notes,
                image_url,
                url
            )
            VALUES (
                p_user_id,
                v_gear_item->>'description',
                v_gear_item->>'item_type',
                v_gear_item->>'brand',
                v_gear_item->>'model',
                (v_gear_item->>'weight_g')::INTEGER,
                (v_gear_item->>'weight_unit_display')::weight_unit_display,
                (v_gear_item->>'consumable')::BOOLEAN,
                (v_gear_item->>'price')::NUMERIC,
                v_gear_item->>'notes',
                v_gear_item->>'image_url',
                v_gear_item->>'url'
            )
            RETURNING id INTO v_gear_id;

            v_gear_items_created := v_gear_items_created + 1;
        END IF;

        -- Add gear_id to array for list
        v_all_gear_ids := array_append(v_all_gear_ids, v_gear_id);

        -- Create listed gear item
        INSERT INTO listed_gear_items (
            gear_id,
            list_category_id,
            quantity,
            worn,
            weight_g_override,
            notes,
            sort_index
        )
        VALUES (
            v_gear_id,
            (v_category_map->>(v_listed_item->>'categoryName'))::UUID,
            (v_listed_item->>'quantity')::INTEGER,
            (v_listed_item->>'worn')::BOOLEAN,
            (v_listed_item->>'weight_g_override')::INTEGER,
            v_listed_item->>'notes',
            (v_listed_item->>'sort_index')::INTEGER
        );

        v_listed_items_created := v_listed_items_created + 1;
    END LOOP;

    -- Update list with all gear_ids for legacy compatibility
    UPDATE lists 
    SET gear_ids = v_all_gear_ids
    WHERE id = v_list_id;

    -- Build return metadata
    v_metadata := jsonb_build_object(
        'gearItemsCreated', v_gear_items_created,
        'gearItemsReused', v_gear_items_reused,
        'categoriesCreated', v_categories_created,
        'listedGearItemsCreated', v_listed_items_created
    );

    -- Return the created list and metadata
    RETURN jsonb_build_object(
        'list', (SELECT row_to_json(lists.*) FROM lists WHERE id = v_list_id),
        'metadata', v_metadata
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant execute permissions
GRANT EXECUTE ON FUNCTION import_complete_list(UUID, JSONB, JSONB, JSONB) TO authenticated;

