import { createClient } from '@supabase/supabase-js'

// Environment-based Supabase configuration
const getSupabaseConfig = () => {
  const environment = import.meta.env.VITE_ENVIRONMENT || 'production'

  // Default to environment variables first
  let supabaseUrl = import.meta.env.VITE_SUPABASE_URL
  let supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY

  // Override with environment-specific variables if they exist
  if (environment === 'development') {
    supabaseUrl = import.meta.env.VITE_SUPABASE_DEV_URL || supabaseUrl
    supabaseAnonKey = import.meta.env.VITE_SUPABASE_DEV_ANON_KEY || supabaseAnonKey
  } else if (environment === 'staging') {
    supabaseUrl = import.meta.env.VITE_SUPABASE_STAGING_URL || supabaseUrl
    supabaseAnonKey = import.meta.env.VITE_SUPABASE_STAGING_ANON_KEY || supabaseAnonKey
  }

  if (!supabaseUrl || !supabaseAnonKey) {
    throw new Error(`Missing Supabase environment variables for ${environment}. Please check your .env.local file.`)
  }

  return { supabaseUrl, supabaseAnonKey, environment }
}

const { supabaseUrl, supabaseAnonKey, environment } = getSupabaseConfig()

export const supabase = createClient(supabaseUrl, supabaseAnonKey)

// Log current environment in development
if (import.meta.env.DEV) {
  console.log(`🗄️  Supabase connected to: ${environment} (${supabaseUrl})`)
}

