    fireEvent.change(passwordInput, { target: { value: 'wrongpassword' } })
    fireEvent.click(submitButton)

    // Assert: Should show the user-friendly error message
    await waitFor(() => {
      expect(screen.getByText('Invalid email or password')).toBeInTheDocument()
    })

    // Should NOT show the confusing technical error
    expect(screen.queryByText('Invalid API key')).not.toBeInTheDocument()
  })

  it('should display user-friendly error message for Invalid login credentials error', async () => {
    // Arrange: Mock another common auth error
    mockSupabaseAuth.signInWithPassword.mockResolvedValue({
      error: { message: 'Invalid login credentials' }
    })

    render(<LoginForm />, { wrapper: TestWrapper })

    // Act: Fill out and submit the form
