    const passwordInput = screen.getByLabelText(/password/i)
    const submitButton = screen.getByRole('button', { name: /sign in/i })

    fireEvent.change(emailInput, { target: { value: 'test@example.com' } })
    fireEvent.change(passwordInput, { target: { value: 'wrongpassword' } })
    fireEvent.click(submitButton)

    // Assert: Should show the user-friendly error message
    await waitFor(() => {
      expect(screen.getByText('Invalid email or password')).toBeInTheDocument()
    })
  })

  it('should display other error messages unchanged', async () => {
    // Arrange: Mock a different type of error that should pass through
    mockSupabaseAuth.signInWithPassword.mockResolvedValue({
      error: { message: 'Network error occurred' }
    })

    render(<LoginForm />, { wrapper: TestWrapper })

    // Act: Fill out and submit the form
    const emailInput = screen.getByLabelText(/email/i)
    const passwordInput = screen.getByLabelText(/password/i)
    const submitButton = screen.getByRole('button', { name: /sign in/i })

    fireEvent.change(emailInput, { target: { value: 'test@example.com' } })
    fireEvent.change(passwordInput, { target: { value: 'password' } })
    fireEvent.click(submitButton)

    // Assert: Should show the original error message
    await waitFor(() => {
      expect(screen.getByText('Network error occurred')).toBeInTheDocument()
    })
  })

  it('should navigate to dashboard on successful login', async () => {
    // Arrange: Mock successful login
    mockSupabaseAuth.signInWithPassword.mockResolvedValue({
      error: null
    })

    render(<LoginForm />, { wrapper: TestWrapper })

    // Act: Fill out and submit the form
    const emailInput = screen.getByLabelText(/email/i)
    const passwordInput = screen.getByLabelText(/password/i)
    const submitButton = screen.getByRole('button', { name: /sign in/i })

    fireEvent.change(emailInput, { target: { value: 'test@example.com' } })
    fireEvent.change(passwordInput, { target: { value: 'password' } })
    fireEvent.click(submitButton)

    // Assert: Should navigate to dashboard
    await waitFor(() => {
      expect(mockNavigate).toHaveBeenCalledWith('/dashboard')
    })

    // Should not show any error
    expect(screen.queryByText('Invalid email or password')).not.toBeInTheDocument()
  })
})

