import { createClient } from '@supabase/supabase-js'

// Environment constants
const ENVIRONMENT_PRODUCTION = 'production'
const ENVIRONMENT_DEVELOPMENT = 'development' 
const ENVIRONMENT_STAGING = 'staging'

// Environment-based Supabase configuration
const getSupabaseConfig = () => {
  const environment = import.meta.env.VITE_ENVIRONMENT

  if (!environment) {
    throw new Error('Missing environment variable VITE_ENVIRONMENT.')
  }

  // Select environment-specific variables based on VITE_ENVIRONMENT
  let supabaseUrl: string
  let supabaseAnonKey: string

  switch (environment) {
    case ENVIRONMENT_PRODUCTION:
      supabaseUrl = import.meta.env.VITE_SUPABASE_URL
      supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY
      break
    case ENVIRONMENT_DEVELOPMENT:
      supabaseUrl = import.meta.env.VITE_SUPABASE_DEV_URL
      supabaseAnonKey = import.meta.env.VITE_SUPABASE_DEV_ANON_KEY
      break
    case ENVIRONMENT_STAGING:
      supabaseUrl = import.meta.env.VITE_SUPABASE_STAGING_URL
      supabaseAnonKey = import.meta.env.VITE_SUPABASE_STAGING_ANON_KEY
      break
    default:
      throw new Error(`Unknown environment: ${environment}. Expected: production, development, or staging.`)
  }

  if (!supabaseUrl || !supabaseAnonKey) {
    throw new Error(`Missing Supabase environment variables for ${environment}.`)
  }

  return { supabaseUrl, supabaseAnonKey, environment }
}

const { supabaseUrl, supabaseAnonKey, environment } = getSupabaseConfig()

export const supabase = createClient(supabaseUrl, supabaseAnonKey)

// Log current environment in development only
if (environment === ENVIRONMENT_DEVELOPMENT) {
  console.log(`🗄️  Supabase connected to: ${environment} (${supabaseUrl})`)
}

